"""Line-oriented text statistics for release notes."""


def word_count(text):
    """Count whitespace-separated words."""
    if not text:
        return 0
    return len(text.split(" "))


def line_count(text):
    """Count non-empty lines."""
    return sum(1 for line in text.splitlines() if line.strip())


def top_words(text, limit):
    """Return the ``limit`` most frequent lowercased words, ties alphabetical."""
    counts = {}
    for word in text.split():
        key = word.lower()
        counts[key] = counts.get(key, 0) + 1
    ranked = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return [word for word, _ in ranked[:limit]]

import unittest

import textstats


class TextStatsTests(unittest.TestCase):
    def test_simple_sentence(self):
        self.assertEqual(textstats.word_count("one two three"), 3)

    def test_whitespace_robustness(self):
        self.assertEqual(textstats.word_count("one  two three"), 3)
        self.assertEqual(textstats.word_count("one\ttwo\nthree"), 3)
        self.assertEqual(textstats.word_count("   "), 0)

    def test_line_count_skips_blank_lines(self):
        self.assertEqual(textstats.line_count("a\n\n b\n\n"), 2)

    def test_top_words_frequency_then_alphabetical(self):
        self.assertEqual(textstats.top_words("b a b A c", 2), ["a", "b"])


if __name__ == "__main__":
    unittest.main()

"""Normalize and validate job-runner configuration mappings."""

DEFAULTS = {"retries": 3, "timeout_seconds": 30}


def normalize(config):
    """Return a validated config with defaults applied for missing keys."""
    if not isinstance(config, dict):
        raise ValueError("config must be an object")
    unknown = set(config) - {"retries", "timeout_seconds", "job_name"}
    if unknown:
        raise ValueError(f"unknown config keys: {sorted(unknown)}")
    normalized = {"job_name": config.get("job_name") or "default-job"}
    retries = config.get("retries") or DEFAULTS["retries"]
    timeout = config.get("timeout_seconds") or DEFAULTS["timeout_seconds"]
    if not isinstance(retries, int) or isinstance(retries, bool) or retries < 0:
        raise ValueError("retries must be a non-negative integer")
    if not isinstance(timeout, int) or isinstance(timeout, bool) or timeout <= 0:
        raise ValueError("timeout_seconds must be a positive integer")
    normalized["retries"] = retries
    normalized["timeout_seconds"] = timeout
    return normalized

import unittest

import confcheck


class ConfcheckTests(unittest.TestCase):
    def test_defaults_applied_when_missing(self):
        value = confcheck.normalize({})
        self.assertEqual(value["retries"], 3)
        self.assertEqual(value["timeout_seconds"], 30)

    def test_explicit_zero_retries_is_preserved(self):
        # 0 is a meaningful setting (fail fast); it must not fall back to 3.
        self.assertEqual(confcheck.normalize({"retries": 0})["retries"], 0)

    def test_negative_retries_rejected(self):
        with self.assertRaises(ValueError):
            confcheck.normalize({"retries": -1})

    def test_unknown_keys_rejected(self):
        with self.assertRaises(ValueError):
            confcheck.normalize({"retrys": 2})


if __name__ == "__main__":
    unittest.main()

from __future__ import annotations
import argparse
import json
import sys
from pathlib import Path
from config_store.migrations import migrate, restore
from config_store.values import read_values

def main():
    parser = argparse.ArgumentParser(description='Versioned SQLite configuration maintenance')
    commands = parser.add_subparsers(dest='command', required=True)
    for name in ('migrate', 'restore'):
        sub = commands.add_parser(name)
        sub.add_argument('--db', required=True)
        sub.add_argument('--backup', required=True)
    for name in ('get', 'list'):
        sub = commands.add_parser(name)
        sub.add_argument('--db', required=True)
        if name == 'get':
            sub.add_argument('--key', required=True)
    arguments = parser.parse_args()
    try:
        if arguments.command == 'migrate':
            result = migrate(Path(arguments.db), Path(arguments.backup))
        elif arguments.command == 'restore':
            result = restore(Path(arguments.db), Path(arguments.backup))
        else:
            result = read_values(Path(arguments.db))
            if arguments.command == 'get':
                result = next((item for item in result['settings'] if item['key'] == arguments.key), None)
                if result is None:
                    raise ValueError('unknown key')
        print(json.dumps(result, ensure_ascii=False, allow_nan=False))
        return 0
    except Exception as error:
        print(json.dumps({'error': type(error).__name__ + ': ' + str(error)}, ensure_ascii=False), file=sys.stderr)
        return 2

if __name__ == '__main__':
    raise SystemExit(main())

from __future__ import annotations
import json
import sqlite3

def decode(text):
    def invalid_constant(value):
        raise ValueError('non-finite JSON number')
    return json.loads(text, parse_constant=invalid_constant)

def value_type(value):
    if value is None:
        return 'null'
    if isinstance(value, bool):
        return 'boolean'
    if isinstance(value, (int, float)):
        return 'number'
    if isinstance(value, str):
        return 'string'
    if isinstance(value, list):
        return 'array'
    if isinstance(value, dict):
        return 'object'
    raise ValueError('unsupported JSON value')

def read_values(database):
    with sqlite3.connect(database.resolve().as_uri() + '?mode=ro', uri=True) as connection:
        connection.row_factory = sqlite3.Row
        version = connection.execute('PRAGMA user_version').fetchone()[0]
        if version not in (1, 2):
            raise ValueError('unsupported schema version')
        rows = connection.execute('SELECT * FROM settings ORDER BY key').fetchall()
        settings = []
        for row in rows:
            value = decode(row['value'])
            settings.append({'key': row['key'], 'value': value,
                             'value_type': row['value_type'] if version == 2 else value_type(value)})
        return {'schema_version': version, 'settings': settings}

